package com.mahesh.empleave.leavetype;import jakarta.persistence.*;import lombok.*;@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class LeaveType{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private String name;@Column(nullable=false) private boolean active=true;public LeaveType(String n){name=n;}public void setActive(boolean v){active=v;}}
